import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const session: ChatSession = {
  sessionId: 'usage-session',
  userId: 'usage-user',
  entries: [{role: 'user', content: 'Look it up.', timestamp: '2026-01-01T00:00:00.000Z'}],
};
const promptBuilder = new PromptBuilder({identity: 'Usage test.'});

function scriptedProvider(rounds: MessageChunk[][]): AIProvider {
  let round = 0;
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      yield* rounds[round++] ?? [];
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

function lookupTools(): ToolRegistry {
  const tools = new ToolRegistry();
  tools.register(
    {name: 'lookup', description: 'Looks up a value.', inputSchema: {type: 'object'}},
    async () => 'found'
  );
  return tools;
}

it('reports the total usage of both provider rounds after a tool call', async () => {
  const rounds: MessageChunk[][] = [
    [
      {type: 'tool_use', toolCall: {id: 'lookup-1', name: 'lookup', input: {}}},
      {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 5, outputTokens: 2, totalTokens: 7}},
    ],
    [
      {type: 'text', text: 'Done.'},
      {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 11, outputTokens: 3, totalTokens: 14}},
    ],
  ];
  const provider = scriptedProvider(rounds);
  const tools = lookupTools();
  let reported: UsageMetadata | undefined;
  const hooks: OrchestratorHooks = {
    afterModelResponse: async (_currentSession, _text, usage) => {
      reported = usage;
    },
  };
  const orchestrator = createChatOrchestrator(provider, promptBuilder, tools, {hooks});

  await orchestrator.processMessage(session);

  expect(reported).toEqual({inputTokens: 16, outputTokens: 5, totalTokens: 21});
});

it('ignores rounds without usage and leaves an entirely unreported turn undefined', async () => {
  const rounds: MessageChunk[][] = [
    [
      {type: 'tool_use', toolCall: {id: 'lookup-1', name: 'lookup', input: {}}},
      {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 5, outputTokens: 2, totalTokens: 7}},
    ],
