  const tools = lookupTools();
  const reported: Array<UsageMetadata | undefined> = [];
  const hooks: OrchestratorHooks = {
    afterModelResponse: async (_currentSession, _text, usage) => {
      reported.push(usage);
    },
  };

  await createChatOrchestrator(provider, promptBuilder, tools, {
    hooks,
